// Builds Muster's built-in panel apps from web/src/panels/apps/ into self-contained HTML files in
// web/panels/, which the backend embeds with include_str!, and the Muster Kit (web/panels/kit.css
// and kit.js) that Muster injects in front of a custom panel opened with `kit: true`. The
// generated files are committed so `cargo build` needs no Deno.
//
// Every built-in starts with the kit's CSS. Its fonts are not in these files: a `/*MK-FONTS*/`
// marker stands in for them and Muster replaces it with @font-face rules (data: URIs of
// web/panels/fonts/) when it serves the panel (src/panel_kit.rs; `servePanelHtml` below does the
// same for the mock daemon), so each font is stored once.
//
//   deno task panels           rebuild web/panels/<app>.html, kit.css and kit.js
//   deno task panels --check   fail if a committed file is out of date (part of `deno task check`)

export const APPS = ["image", "chart", "table", "pr_decision", "pr_overview"] as const;
type App = typeof APPS[number];
const TITLES: Record<App, string> = {
  image: "Muster image", chart: "Muster chart", table: "Muster table", pr_decision: "Muster PR decision",
  pr_overview: "Muster PR overview",
};
/** Styles an app takes from another app's folder, before its own. */
const EXTRA_CSS: Partial<Record<App, string[]>> = {};
export const FONT_MARKER = "/*MK-FONTS*/";

const web = new URL("../", import.meta.url);
const read = (path: string) => Deno.readTextFile(new URL(path, web));

async function bundle(entry: string): Promise<string> {
  const out = await new Deno.Command(Deno.execPath(), {
    args: ["bundle", "--platform=browser", "--format=iife", entry],
    cwd: web, stdout: "piped", stderr: "piped",
  }).output();
  if (!out.success) throw new Error(`deno bundle ${entry} failed:\n${new TextDecoder().decode(out.stderr)}`);
  return new TextDecoder().decode(out.stdout);
}

/** A script that is safe inside an inline <script> element. */
function inlineScript(js: string, what: string): string {
  // A literal "</script" would end the element early.
  js = js.replace(/<\/(script)/gi, "<\\/$1");
  if (js.includes("<!--")) throw new Error(`${what}: bundle contains "<!--", which inline scripts cannot hold safely`);
  return js;
}

async function kitCss(): Promise<string> {
  const css = await read("src/panels/kit/kit.css");
  if (css.split(FONT_MARKER).length !== 2) throw new Error(`kit.css must hold ${FONT_MARKER} exactly once`);
  if (/<\/style/i.test(css)) throw new Error("kit.css contains </style");
  return css;
}

export async function build(app: App): Promise<string> {
  const js = inlineScript(await bundle(`src/panels/apps/${app}/main.ts`), app);
  const parts = ["shared/base.css", ...(EXTRA_CSS[app] ?? []).map((a) => `${a}/style.css`), `${app}/style.css`];
  const css = [await kitCss(), ...(await Promise.all(parts.map((p) => read(`src/panels/apps/${p}`))))].join("\n");
  if (/<\/style/i.test(css)) throw new Error(`${app}: CSS contains </style`);
  return `<!doctype html>
<!-- Generated by web/dev/build_panels.ts from web/src/panels/apps/${app}/. Do not edit; run \`deno task panels\`. -->
<html class="mk" lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>${TITLES[app]}</title>
<style>
${css}</style></head><body><main id="app"></main>
<script>
"use strict";
${js}</script></body></html>
`;
}

/** The kit for custom panels: kit.css (with the font marker) and kit.js (safe to inline). */
export async function buildKit(): Promise<{ css: string; js: string }> {
  const js = inlineScript(await bundle("src/panels/kit/main.ts"), "kit");
  return { css: await kitCss(), js: `// Generated by web/dev/build_panels.ts from web/src/panels/kit/. Do not edit; run \`deno task panels\`.\n"use strict";\n${js}` };
}

const base64 = (b: Uint8Array) => {
  let s = "";
  for (let i = 0; i < b.length; i += 0x8000) s += String.fromCharCode(...b.subarray(i, i + 0x8000));
  return btoa(s);
};

/** The @font-face rules Muster puts in place of the marker (src/panel_kit.rs `font_faces`). */
export async function fontFaces(): Promise<string> {
  const font = async (file: string) => `data:font/woff2;base64,${base64(await Deno.readFile(new URL(`panels/fonts/${file}`, web)))}`;
  return `@font-face{font-family:"MK Inter";font-weight:100 900;font-style:normal;font-display:block;src:url(${await font("inter-latin.woff2")}) format("woff2")}` +
    `@font-face{font-family:"MK Mono";font-weight:100 800;font-style:normal;font-display:block;src:url(${await font("jetbrains-mono-latin.woff2")}) format("woff2")}`;
}

/** What a panel's HTML becomes when it is served, like src/panel_kit.rs `serve`: a built-in gets
 * its fonts; a custom panel opened with `kit: true` gets the kit in front of the agent's HTML. */
export async function servePanelHtml(app: string, kit: boolean, html: string): Promise<string> {
  const fonts = await fontFaces();
  if (app !== "custom") return html.replace(FONT_MARKER, fonts);
  if (!kit) return html;
  const [css, js] = await Promise.all([read("panels/kit.css"), read("panels/kit.js")]);
  return `<style>${css.replace(FONT_MARKER, fonts)}</style><script>${js}</script>` + html;
}

if (import.meta.main) {
  const check = Deno.args.includes("--check");
  const stale: string[] = [];
  const kit = await buildKit();
  const outputs: [string, string][] = [["kit.css", kit.css], ["kit.js", kit.js]];
  for (const app of APPS) outputs.push([`${app}.html`, await build(app)]);
  for (const [name, text] of outputs) {
    const target = new URL(`panels/${name}`, web);
    const current = await Deno.readTextFile(target).catch(() => "");
    if (current === text) continue;
    if (check) stale.push(`web/panels/${name}`);
    else {
      await Deno.writeTextFile(target, text);
      console.log(`wrote web/panels/${name} (${text.length} bytes)`);
    }
  }
  if (stale.length) {
    console.error(`Out of date: ${stale.join(", ")}. Run \`cd web && deno task panels\` and commit the result.`);
    Deno.exit(1);
  }
}
